    82	    public synchronized Reservation cancel(long reservationId) {
    83	        Reservation reservation = find(reservationId);
    84	        if (reservation.status() != ReservationStatus.PENDING
    85	                && reservation.status() != ReservationStatus.CONFIRMED) {
    86	            throw notAllowed(reservation, "cancel");
    87	        }
    88	        RatePlanStrategy strategy = RatePlanStrategies.strategyFor(reservation.ratePlan());
    89	        BigDecimal refund = strategy.calculateRefund(reservation);
    90	        reservation.cancel(refund);
    91	        return reservation;
    92	    }
